 $('quadHint').textContent='G\u1eaeN L\u1ea0I '+s.name+': b\u1ea5m \u0111\u00fang m\u1eb7t tr\u01b0\u1edbc c\u1ee7a m\u00e0n LED tr\u00ean s\u00e2n kh\u1ea5u. Gi\u1eef nguy\u00ean video/crop. Esc: h\u1ee7y.';
 $('quadHint').classList.remove('hidden');renderUI();
