function rigPreset(name,history=true){if(history)checkpoint();let w=engine.size.width,h=engine.size.height,d=Math.max(engine.size.depth,5);let colors=name==='warm'?['#ffd09a','#ffb86b']:name==='cool'?['#d6eeff','#7fc9ff']:['#66d5ff','#be7bff'];engine.lights=Array.from({length:8},(_,i)=>({id:'light_'+i,name:'Moving head '+String(i+1).padStart(2,'0'),pos:[(i/7-.5)*w*.83,h*.93,-d*.23],target:[(i/7-.5)*w*(name==='concert'?-.45:.65),.25,d*.55],color:colors[i%2],power:name==='blackout'?0:name==='warm'?3.2:4.5,angle:name==='cool'?24:15,enabled:name!=='blackout',sweep:name==='concert',speed:.35,phase:i*.4,fx:'steady',fxDepth:.55,fxSpeed:2.2,boost:1}));state.selectedLight=engine.lights[0].id;engine.settings.ambient=name==='blackout'?.12:name==='warm'?.65:.8;engine.settings.beam=name==='blackout'?0:.6;engine.rebuildFixtures();if(history){renderUI();toast('Da ap preset anh sang: '+name)}}
