 const mediaSource=state.media.map(a=>({id:a.id,name:a.name,file:a.file}));
 const total=(live.audioTrack?.file?.size||0)+modelFilesSource.reduce((n,f)=>n+f.size,0)+mediaSource.reduce((n,a)=>n+(a.file?.size||0),0);
 if(total>300*1024*1024)throw Error('Gói dự án vượt 300 MB. Hãy dùng video proxy nhẹ hơn trước khi lưu.');
 if(mediaSource.some(a=>!a.file))throw Error('Có media không còn tệp nguồn. Hãy nạp lại media trước khi lưu.');
 const screens=engine.surfaces.map(s=>{const out={...s};delete out.testCanvas;out.mesh={name:s.mesh.name,p:encodeFloats(s.mesh.p),uv:encodeFloats(s.mesh.uv),n:encodeFloats(s.mesh.n)};return out;});
 const data=JSON.parse(JSON.stringify({format:'ALPHA_LED_STUDIO/0.2',appVersion:'15.1.0',coordinates:engine.coordinates,layout:engine.layout,savedAt:new Date().toISOString(),model:{name:state.model.name,demo:state.model.demo,files:[]},media:[],screens,master:engine.master,settings:engine.settings,lights:engine.lights,camera:engine.camera,accent:engine.accent,effect:engine.effect,duration:state.duration,time:state.time}));
