 try{const data=await buildProjectData142();downloadText((data.model.name.replace(/\.[a-z0-9]+$/i,'')||'Stage')+'.ledstudio',JSON.stringify(data));toast('Đã lưu dự án V14.2 kèm model, media và cue FX.');return data;}
 catch(e){toast('Không lưu được dự án: '+e.message,8000);return null;}
